// /sysadmin/app-map — a flat, readable map of the whole application.
//
// This is a DEVELOPER aid, not a product surface: it lists every page, who
// sees it, what data it loads, and what each button does — in plain English.
// It reads the generated .app-map.json (regenerated by `npm run app-map`),
// which is itself a heuristic scan of src/app/**/page.tsx. The map stays
// current automatically; it becomes one fewer thing to maintain by hand.
//
// Access: this route group is wrapped in AuthGuard allowedRoles=["sysadmin"],
// so only sysadmin can open it. The page is intentionally plain HTML (no
// rich UI) — it is meant to be scanned, not polished.
"use client";

import { Suspense, useCallback, useEffect, useMemo, useState } from "react";
import { PageHeader } from "@/components/shared/PageHeader";
import { PageLoading } from "@/components/shared/LoadingStates";
import { useApiResource } from "@/hooks/useApiResource";
import { ContextSituationBar } from "@/components/shared/ContextSituationBar";

interface ButtonEntry {
  label: string;
  handler: string | null;
  action: string | null;
  capability: string | null;
}
interface FetchCall {
  method: string;
  url: string;
}
interface PageEntry {
  route: string;
  file: string;
  title: string | null;
  subtitle: string | null;
  role: string | null;
  fetches: FetchCall[];
  buttons: ButtonEntry[];
  capabilities: string[];
  navEntry: { label: string; href: string } | null;
}
interface AppMap {
  generatedAt: string;
  pageCount: number;
  pages: PageEntry[];
}

const ROLE_LABELS: Record<string, string> = {
  student: "Students",
  supervisor: "Supervisors",
  operator: "Gate Operators",
  principal: "Principal / Warden",
  hod: "HODs / Academics",
  faculty: "Faculty",
  staff: "Staff",
  visitor: "Visitors",
  worker: "Workers",
  guardian: "Guardians / Parents",
  mess: "Mess",
  approver: "Approvers",
  sysadmin: "SysAdmin",
  admin: "SysAdmin",
  exam: "Examinations",
  "exam-branch": "Exam Branch",
  "exam-superintendent": "Exam Superintendent",
};

function roleLabel(role: string | null): string {
  if (!role) return "Unassigned";
  return ROLE_LABELS[role] ?? role;
}

function AppMapInner() {
  const { data, error, loading } = useApiResource<AppMap>("/api/dev/app-map", {
    ttlMs: 3600_000,
  });
  const [filterRole, setFilterRole] = useState<string>("all");
  const [query, setQuery] = useState("");

  const roles = useMemo(() => {
    const s = new Set<string>();
    for (const p of data?.pages ?? []) if (p.role) s.add(p.role);
    return [...s].sort();
  }, [data]);

  const filtered = useMemo(() => {
    if (!data) return [];
    return data.pages.filter((p) => {
      if (filterRole !== "all" && p.role !== filterRole) return false;
      if (query) {
        const q = query.toLowerCase();
        return (
          p.route.toLowerCase().includes(q) ||
          (p.title ?? "").toLowerCase().includes(q) ||
          p.file.toLowerCase().includes(q)
        );
      }
      return true;
    });
  }, [data, filterRole, query]);

  // Group by role, preserving role order.
  const grouped = useMemo(() => {
    const map = new Map<string, PageEntry[]>();
    for (const p of filtered) {
      const key = p.role ?? "unassigned";
      if (!map.has(key)) map.set(key, []);
      map.get(key)!.push(p);
    }
    return map;
  }, [filtered]);

  const handleRegen = useCallback(async () => {
    // Trigger a fresh scan (best-effort; the committed JSON is the source of
    // truth until the next build). We revalidate the cache via the query param.
    const res = await fetch("/api/dev/app-map?bust=" + Date.now());
    if (res.ok) {
      const fresh = (await res.json()) as AppMap;
      // Refetch via the hook's cache-bust is not available; reload is the
      // simplest, most reliable path for a dev aid.
      window.location.reload();
      void fresh;
    }
  }, []);

  return (
    <div className="max-w-4xl mx-auto px-4 py-6 space-y-6">
      <ContextSituationBar
        roleLabel="System Admin"
        purpose="Manage and monitor application map for campus operations."
        contextLabel="Application Map"
        statusSummary="Review current application map state and take action below."
        primaryAction={{ label: "SysAdmin Overview", href: "/sysadmin" }}
        secondaryAction={{ label: "System Health", href: "/sysadmin/health" }}
      />
      <PageHeader
        title="Application Map"
        subtitle={`A flat, readable view of every page · ${data?.pageCount ?? 0} pages · generated ${data?.generatedAt ? new Date(data.generatedAt).toLocaleString() : "…"}`}
      />

      {loading ? (
        <PageLoading />
      ) : error ? (
        <div className="rounded-lg border border-amber-200 bg-amber-50 p-4 text-sm text-amber-800">
          Map not available: {String(error)}
          <div className="mt-2 text-xs text-amber-600">
            Run <code className="font-mono">npm run app-map</code> to regenerate{" "}
            <code className="font-mono">.app-map.json</code>, then rebuild.
          </div>
        </div>
      ) : (
        <>
          <div className="flex flex-wrap items-center gap-2 text-sm">
            <label className="text-text-primary font-medium">Role:</label>
            <select
              value={filterRole}
              onChange={(e) => setFilterRole(e.target.value)}
              className="rounded-md border border-border bg-background px-2 py-1 text-sm"
            >
              <option value="all">All roles</option>
              {roles.map((r) => (
                <option key={r} value={r}>
                  {roleLabel(r)}
                </option>
              ))}
            </select>
            <input
              type="search"
              placeholder="Filter by route / title / file…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="w-64 rounded-md border border-border bg-background px-2 py-1 text-sm"
            />
            <button
              type="button"
              onClick={handleRegen}
              className="ml-auto rounded-md border border-border bg-action-primary px-3 py-1 text-sm text-white hover:bg-action-primary-hover"
            >
              Re-read map
            </button>
          </div>

          {[...grouped.entries()].map(([role, pages]) => (
            <section key={role} className="space-y-3">
              <h2 className="text-xs font-semibold uppercase tracking-wider text-action-primary">
                {roleLabel(role)}{" "}
                <span className="font-normal text-text-muted">
                  ({pages.length})
                </span>
              </h2>
              <div className="space-y-2">
                {pages.map((p) => (
                  <article
                    key={p.route}
                    className="rounded-lg border border-border bg-card p-3 text-sm"
                  >
                    <div className="flex items-center justify-between gap-2">
                      <div className="font-medium">{p.title ?? p.route}</div>
                      <code className="text-xs text-muted-foreground">{p.route}</code>
                    </div>
                    {p.subtitle && (
                      <div className="mt-0.5 text-xs text-muted-foreground">
                        {p.subtitle}
                      </div>
                    )}
                    <div className="mt-2 space-y-1 text-xs">
                      <div>
                        <span className="text-text-secondary">file: </span>
                        <code className="text-text-muted">{p.file}</code>
                      </div>
                      {p.fetches.length > 0 && (
                        <div>
                          <span className="text-text-secondary">loads: </span>
                          <span className="text-text-muted">
                            {p.fetches
                              .map((f) => `${f.method} ${f.url}`)
                              .join(" · ")}
                          </span>
                        </div>
                      )}
                      {p.capabilities.length > 0 && (
                        <div>
                          <span className="text-text-secondary">gates: </span>
                          <span className="text-text-muted">
                            {p.capabilities.join(", ")}
                          </span>
                        </div>
                      )}
                      {p.buttons.length > 0 && (
                        <div>
                          <span className="text-text-secondary">actions: </span>
                          <span className="text-text-muted">
                            {p.buttons
                              .map((b) =>
                                b.action
                                  ? `${b.label} → ${b.action}`
                                  : `${b.label} (describe me)`,
                              )
                              .join(" · ")}
                          </span>
                        </div>
                      )}
                    </div>
                  </article>
                ))}
              </div>
            </section>
          ))}
        </>
      )}
    </div>
  );
}

export default function AppMapPage() {
  return (
    <Suspense fallback={<PageLoading />}>
      <AppMapInner />
    </Suspense>
  );
}
